  "sim.egg-incubator.title": "달걀 부화기",
  "sim.egg-incubator.desc": "부화장에 있는 온도, 습도, 달걀 회전을 관리해 부화율을 극대화하세요.",
  "sim.dairy-farm.title": "낙농 농장",
  "sim.dairy-farm.desc": "소규모 낙농 운영을 진행하세요: 사료 급여 일정, 착유 주기, 무리 건강 관리를 통해 생산량을 극대화합니다.",
  "sim.poultry-farm.title": "가금 농장",
  "sim.poultry-farm.desc": "상업용 가금 농장을 운영하세요 — 육계와 산란계 무리의 사료, 건강, 생산 목표를 관리합니다.",
  "sim.cattle-dairy.title": "축산 & 낙농",
  "sim.cattle-dairy.desc": "목초지 관리, 번식, 우유 생산의 균형을 맞추며 소 목장과 낙농 유닛을 감독하세요.",
  "sim.sheep-farm.title": "양 농장",
  "sim.sheep-farm.desc": "계절별 사이클로 양 농장을 운영하세요: 번식, 깎기(사이링), 시장 판매.",
  "sim.network-noc.title": "네트워크 NOC",
  "sim.network-noc.desc": "네트워크 운영 센터 엔지니어로서 활발한 인프라 사고를 압박 속에서도 진단하고 해결하세요.",
  "sim.mobile-repair.title": "모바일 수리 작업장",
  "sim.mobile-repair.desc": "스마트폰을 진단하고 수리하세요 — 화면 교체, 배터리 문제, 마더보드 고장.",
  "sim.laptop-repair.title": "노트북 수리 작업장",
  "sim.laptop-repair.desc": "노트북을 문제 해결하고 수리하세요: 하드웨어 고장, BIOS 문제, 부품 교체.",
  "sim.perfume-lab.title": "퍼퓸 랩",
  "sim.perfume-lab.desc": "필수 오일과 향 성분을 블렌딩해 시그니처 향을 만들고 품질 벤치마크를 달성하세요.",
  "sim.detergent-lab.title": "세제 연구소",
  "sim.detergent-lab.desc": "세정 제품을 배합하세요 — 계면활성제, 필러, 성능 테스트를 예산 안에서 균형 있게 조정합니다.",
  "sim.skin-care-lab.title": "스킨케어 연구소",
  "sim.skin-care-lab.desc": "화장품 제형을 개발하고 테스트하세요. 안전 기준과 효능 목표를 충족해야 합니다.",
  "sim.woodworking.title": "목공 작업장",
  "sim.woodworking.desc": "맞춤형 목공 매장을 운영하세요: 작업을 계획하고 자재를 관리하며 가구를 예산과 일정에 맞춰 납품하세요.",
  "sim.aluminum-glazing.title": "알루미늄 & 글레이징",
  "sim.aluminum-glazing.desc": "견적부터 현장 완료까지 알루미늄 가공 및 유리 설치 사업을 관리하세요.",
  "sim.global-kitchen.title": "글로벌 키친",
  "sim.global-kitchen.desc": "레스토랑 키친을 이끌어 보세요 — 서비스 교대 전반에 걸쳐 메뉴, 직원, 비용, 고객 만족도를 관리합니다.",
  "sim.chocolate-factory.title": "초콜릿 공장",
  "sim.chocolate-factory.desc": "제과 공장을 운영하세요 — 카카오 소싱, 생산 일정 관리, 품질 관리.",
  "sim.solar-energy.title": "태양 에너지 플랜트",
  "sim.solar-energy.desc": "태양광 설치를 설계하고 운영하세요 — 패널 크기 산정, 그리드 수출 관리, ROI(투자수익률) 추적.",
  "sim.hvac-systems.title": "HVAC 시스템",
  "sim.hvac-systems.desc": "상업용 건물에 난방, 환기, 공조 시스템을 설치하고 유지보수하세요.",
  "sim.logistics-supply.title": "물류 & 공급망",
  "sim.logistics-supply.desc": "창고 운영, 차량 경로, 공급업체 관계를 최적화해 납기 KPI를 달성하세요.",
  "sim.barber-salon.title": "바버 샵",
  "sim.barber-salon.desc": "미용실(이발소)을 운영하세요: 예약, 직원 스케줄, 가격, 고객 유지 전략을 관리합니다.",
  "sim.board-surgeon.title": "보드 서전",
  "sim.board-surgeon.desc": "시뮬레이션 수술실에서 고위험 수술 결정을 내리세요 — 시간 관리와 환자 안전.",
  "sim.english-journey.title": "영어 여정",
  "sim.english-journey.desc": "구조화된 영어 프로그램으로 학습자를 지도하되, 다양한 숙련도에 맞춰 조정하세요.",
  "sim.music-training.title": "음악 훈련 스튜디오",
  "sim.music-training.desc": "음악 학교를 운영하세요 — 수업을 스케줄링하고 악기를 관리하며 학생들이 리사이틀까지 나아가는 진행 상황을 추적하세요.",
  "sim.trade-tycoon.title": "트레이드 타이쿤",
  "sim.trade-tycoon.desc": "거래 제국을 구축하세요 — 싸게 사서 비싸게 팔고, 여러 시장에 걸쳐 재고와 현금 흐름을 관리합니다.",
  "sim.vehicle-diagnostics.title": "차량 진단 & 수리 시뮬레이터",
  "sim.vehicle-diagnostics.desc": "OBD-II 고장 코드를 진단하고 전기 고장을 추적하며, 실제 자동차 수리 작업 흐름을 관리하세요.",
  "sim.marine-vessel.title": "해상 선박 추적 & 해운 물류",
  "sim.marine-vessel.desc": "전 세계 선단을 지휘하세요 — 선박을 추적하고 항만 정체, 기상 비상, 운하 지연을 대비해 항로를 안내합니다.",
