  "jungle.s6c2": "그냥 두세요 — 돌보느라 에너지가 낭비돼요 (0 HP, +10 pts)",
  "jungle.scene7": "강이 길을 가로막고 있어요. 물이 빨라 보입니다.",
  "jungle.s7c1": "쓰러진 통나무로 뗏목을 만드세요 (−5 HP, +40 pts)",
  "jungle.s7c2": "상류로 걸어 얕은 곳을 찾아 건너세요 (+10 HP, +20 pts)",
  "jungle.scene8": "멀리서 연기가 보입니다.",
  "jungle.s8c1": "연기 쪽으로 가세요 — 구조일 수도! (+15 HP, +45 pts)",
  "jungle.s8c2": "피하세요 — 산불일 수도 있어요 (−5 HP, +15 pts)",
  "jungle.scene9": "밤이 내려요. 피난처가 필요합니다.",
  "jungle.s9c1": "높은 나무에 올라 포식자로부터 안전하게 지내세요 (+10 HP, +30 pts)",
  "jungle.s9c2": "나뭇가지를 이용해 바닥 피난처를 만드세요 (−5 HP, +35 pts)",
  "jungle.scene10": "정체를 알 수 없는 과일을 발견했어요. 정말 배가 고파요.",
  "jungle.s10c1": "먹어버리세요 — 너무 굶었어요! (−20 HP, +30 pts)",
  "jungle.s10c2": "먼저 피부에 아주 조금만 테스트해요 (0 HP, +20 pts)",
  "jungle.scene11": "큰 뱀이 길 위에 감겨 있습니다.",
  "jungle.s11c1": "천천히 뒤로 물러나 우회로를 찾으세요 (+5 HP, +30 pts)",
  "jungle.s11c2": "겁주어서 쫓아보세요 (−25 HP, +40 pts)",
  "jungle.scene12": "폭포 소리가 들려요 — 물 공급이 치명적으로 부족합니다.",
  "jungle.s12c1": "소리를 따라 가서 마실 물을 찾으세요 (+20 HP, +35 pts)",
  "jungle.s12c2": "무시하고 계속 전진해요 (−15 HP, +20 pts)",
  "jungle.scene13": "폭풍이 빠르게 다가오고 있어요.",
  "jungle.s13c1": "높은 곳을 찾아 몸을 숨기세요 (+10 HP, +25 pts)",
  "jungle.s13c2": "벗어나기 위해 계속 움직이세요 (−10 HP, +30 pts)",
  "jungle.scene14": "동굴을 발견했어요. 점점 어두워지고 있습니다.",
  "jungle.s14c1": "동굴 안으로 들어가 피하세요 (+15 HP, +30 pts)",
  "jungle.s14c2": "나무 아래에서 자요 — 동굴이 누군가 차지했을 수도 (+5 HP, +20 pts)",
  "jungle.scene15": "너무 지쳤어요. 앞이 트인 곳이 안전해 보여요.",
  "jungle.s15c1": "쉬면서 회복하세요 (+20 HP, +20 pts)",
  "jungle.s15c2": "계속 밀고 나가요 — 여기서는 쉬는 게 위험해요 (−5 HP, +30 pts)",
  "jungle.scene16": "나무에 새겨진 오래된 지도를 발견했어요.",
  "jungle.s16c1": "지도가 가리키는 방향을 따라가세요 (+5 HP, +40 pts)",
  "jungle.s16c2": "그냥 무시하세요 — 오래됐을지도 몰라요 (0 HP, +10 pts)",
  "jungle.scene17": "야생 멧돼지가 길을 공격적으로 가로질러요.",
  "jungle.s17c1": "가장 가까운 나무로 즉시 올라가세요 (+5 HP, +30 pts)",
  "jungle.s17c2": "자리를 지키고 소리쳐요 (−20 HP, +35 pts)",
  "jungle.scene18": "보급품이 있는 버려진 야영지를 발견했어요.",
  "jungle.s18c1": "유용한 건 전부 가져가세요 (+20 HP, +50 pts)",
  "jungle.s18c2": "그냥 두세요 — 나중에 누군가 필요할 수도 있어요 (0 HP, +10 pts)",
  "jungle.scene19": "원숭이가 당신의 식료품 가방을 훔쳐요!",
  "jungle.s19c1": "원숭이를 쫓아가세요 (−10 HP, +40 pts)",
  "jungle.s19c2": "그만두세요 — 에너지 낭비예요 (+0 HP, +15 pts)",
  "jungle.scene20": "머리 위에서 헬리콥터 소리가 들려요.",
  "jungle.s20c1": "지금 바로 신호불을 피우세요! (+30 HP, +60 pts)",
  "jungle.s20c2": "팔을 흔드세요 — 당신을 볼 수도 있어요 (+5 HP, +40 pts)",
