  "akinator.char.ronaldo": "크리스티아누 호날두",
  "akinator.char.messi": "리오넬 메시",
  "akinator.howTo.1": "실존 인물이든 가상 인물이든 떠올려 보세요",
  "akinator.howTo.2": "질문에 정직하게 답하세요 (Yes/Probably/Don't Know/Probably Not/No)",
  "akinator.howTo.3": "AI는 답변할 때마다 후보를 좁혀요",
  "akinator.howTo.4": "Akinator가 20문항 안에 당신의 캐릭터를 맞출 수 있는지 확인해 보세요!",
  "neonbreach.howTo.1": "켜진 노드의 순서를 주의 깊게 보세요",
  "neonbreach.howTo.2": "그런 다음 탭해서 똑같은 순서로 다시 따라 하세요",
  "neonbreach.howTo.3": "정답일 때마다 기억할 노드가 1개씩 늘어요",
  "neonbreach.howTo.4": "한 번만 잘못 탭해도 방화벽에 걸려요!",
  "earmaster.howTo.1": "재생되는 음악 음을 주의 깊게 들어보세요",
  "earmaster.howTo.2": "7가지 중에서 들었던 음을 선택하세요",
  "earmaster.howTo.3": "재생 버튼으로 한 번 더 음을 들어보세요",
  "earmaster.howTo.4": "10라운드를 모두 완료해 최종 점수를 확인하세요",
  "uno.howTo.1": "도미노 체인의 양끝 숫자(또는 색)를 맞추세요",
  "uno.howTo.2": "손에 있는 카드를 탭해 내세요",
  "uno.howTo.3": "맞는 카드가 없으면 Draw를 탭해 카드를 추가하세요",
  "uno.howTo.4": "손패를 먼저 비우는 사람이 이겨요!",
  "briscola.howTo.1": "브리콜라는 이탈리아의 트릭 테이킹 카드 게임이에요",
  "briscola.howTo.2": "트럼프 슈트(브리콜라)는 다른 모든 슈트를 이겨요",
  "briscola.howTo.3": "트릭을 따서 점수를 얻으세요 — 에이스=11, 3=10, 킹=4, 퀸=3, 잭=2",
  "briscola.howTo.4": "모든 카드를 다 낸 뒤 최고 점수가 이겨요",
  "card99.howTo.1": "합계가 99를 넘지 않도록 카드를 내세요",
  "card99.howTo.2": "특수 카드: 킹=0, 퀸=유지, 잭=−10, 에이스=1 또는 11",
  "card99.howTo.3": "합계가 99를 넘으면 목숨을 잃어요",
  "card99.howTo.4": "마지막까지 남은 사람이(목숨 보유) 이겨요!",
  "dominoes.howTo.1": "도미노 체인의 양끝 숫자를 맞추세요",
  "dominoes.howTo.2": "열린 끝과 일치하는 타일을 손에서 내세요",
  "dominoes.howTo.3": "낼 수 없으면 더미에서 뽑으세요",
  "dominoes.howTo.4": "손패를 먼저 비우는 사람(또는 눈금 총합이 가장 적은 사람)이 이겨요!",
  "farkle.howTo.1": "주사위 6개를 굴리고 점수 주사위는 따로 치워두세요",
  "farkle.howTo.2": "1s = 100 pts · 5s = 50 pts · 같은 종류 3개 = (면) × 100",
  "farkle.howTo.3": "굴린 결과에서 NO dice가 점수를 얻지 못하면 FARKLE — 턴을 잃어요!",
  "farkle.howTo.4": "점수를 저장해 두거나, 더 많은 위험/보상으로 다시 굴리세요",
